import{_ as e,o,c as t,a3 as _}from"./chunks/framework.DdpBa4_E.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/money-dog/03-童话与理财.md","filePath":"books/money-dog/03-童话与理财.md","lastUpdated":1794316978000}'),a={name:"books/money-dog/03-童话与理财.md"};function s(n,p,r,d,c,m){return o(),t("div",null,[...p[0]||(p[0]=[_("<p>童话与理财</p><p>二十五年前我曾写过一首诗：</p><p>坐在屋子里</p><p>看墙上的风景画</p><p>在画框里</p><p>坐在窗户旁</p><p>看外面的风景</p><p>在窗框里</p><p>走下楼去</p><p>想看一看原野</p><p>高楼和烟囱</p><p>横在风景上</p><p>想看一幅风景</p><p>没有画框的风景</p><p>我知道</p><p>我还要走很远很远</p><p>当时的我不无伤感地表达了：在这个绚丽、复杂、多变的都市，我们离简单和真实已经有很远很远的距离了，无论是在现实世界，还是在我们的心里。</p><p>我们从教科书中知道，很久很久以前，货币（金钱）是为方便人们进行货物交换而诞生的，是为人服务的。然而在今天这个财富的时代，这个初衷却似乎已经如同诗中的风景，远离了我们。</p><p>近些年，中国变化迅猛，眼前耳边，媒体上关于企业家的报道和各种财富故事纷至沓来。国外的不说，单就国内的各种评述、渲染已是不绝于耳。他们在崛起的市场经济中，或叱咤风云，或激烈厮杀，或神秘莫测，或鞠躬尽瘁，或厚黑有术……凡此种种，无不给投资理财蒙上了一层厚重的面纱，似乎与财富相关的一切都离我们普通百姓的生活太远、太远了。</p><p>于是有人说：赚钱太累！那是“他们”才能做到的事。</p><p>想看一幅没有画框的风景，现在想来也许并没有之前所说的那么伤感，要走“很远很远”。</p><p>关键在于你的心态，在你的心里究竟还有多少框框——“名人”的框框、习惯的框框、观念的框框……</p><p>当然，对于框框我们不可能也不可以视而不见，但最重要的是在看见框框的同时，你是否也看见了里面的风景。这需要勇气和信心，而真正的勇敢是在感到最恐惧的时候，你依然在往前走。</p><p>这本书让我想起了我最喜爱的一句话：如果你想富有，请把自己变成一个小孩。因为小孩子的框框最少，他们诚实、快乐、乐于学习。</p><p>本书的主人公小姑娘吉娅和她可爱的小狗——钱钱，一同为你讲述了一个童话般的理财故事，一切从一本成功日记、一个梦想储蓄罐开始……</p><p>这样的故事正不断地在我们身边发生着，只要你认为我们的生活也必须过得更好。事实上，理财和实现富有对老百姓来说未必只意味着沉重与艰辛；理财和你热爱的其他任何事业都可如童话般有趣，如童话般简单。只要你诚实、自信、轻松、快乐，并乐于学习。</p><p>你会发现这幅富有的风景画原本就在你身边。</p><p>而你也将在你童话般的理财生活中发现自己既平凡又伟大！</p><p>汤小明</p><p>2013年岁末</p>",30)])])}const f=e(a,[["render",s]]);export{l as __pageData,f as default};
